17_quadrati.R.code:
x17 <- c(2, 4, 6)
scarti2 <- function(a) {
  sum((x17 - a)^2)
}
sapply(c(3, 4, 5), scarti2)
# 11, 8, 11: minimo in a = 4

19_assoluti.R.code:
x19 <- c(2, 4, 6)
scarti1 <- function(a) {
  sum(abs(x19 - a))
}
sapply(c(3, 4, 5), scarti1)
# 5, 4, 5: minimo in a = 4

38_banda.R.code:
k15 <- density(diam, bw = .15,
  from = 2, to = 14, n = 256)
k40 <- density(diam, bw = .4,
  from = 2, to = 14, n = 256)
k12 <- density(diam, bw = 1.2,
  from = 2, to = 14, n = 256)
plot(k15, xlim = c(3,9),
     ylim = c(0,.65))
lines(k40, col = 2)
lines(k12, col = 4)

